END_VAR

IF StopPB OR NOT GuardClosed OR Fault THEN
    Conveyor := FALSE;
ELSIF StartPB AND GuardClosed AND NOT Fault THEN
    Conveyor := TRUE;
ELSIF Conveyor AND (StopPB OR NOT GuardClosed OR Fault) THEN
    Conveyor := FALSE;
