        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        NS_Green(IN := FALSE, PT := T#0s);
        NS_Yellow(IN := FALSE, PT := T#0s);
        NS_AllRed(IN := TRUE, PT := T#1s);
        EW_Green(IN := FALSE, PT := T#0s);
        EW_Yellow(IN := FALSE, PT := T#0s);
        EW_AllRed(IN := FALSE, PT := T#0s);
END_CASE;

// Advance state after timers expire
IF NOT NS_Green.Q AND NOT NS_Yellow.Q AND NOT NS_AllRed.Q THEN
    State := State + 1;
ELSIF NOT EW_Green.Q AND NOT EW_Yellow.Q AND NOT EW_AllRed.Q THEN
    State := State + 1;
END_IF;

// Reset state if it goes out of bounds
IF State > 5 THEN
    State := 0;
END_IF;

END_PROGRAM

