PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET THEN
    State := 3;
ELSIF State = 3 AND PT_REACT <= T#0s THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        IF Level >= LVL_HIGH THEN
            FillValve := FALSE;
        ELSE
            FillValve := TRUE;
        END_IF;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;
        FillValve := FALSE;
        DrainValve := FALSE;
    3:
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;
        FillValve := FALSE;
        DrainValve := FALSE;
    4:
        IF Level <= LVL_LOW THEN
            DrainValve := FALSE;
        ELSE
            DrainValve := TRUE;
        END_IF;
        Heater := FALSE;
        Agitator := FALSE;
        FillValve := FALSE;
END_CASE;

IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

