            DrainValve := FALSE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;
        3: -- React
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            IF FillTimer.Q THEN
                State := 4;
            END_IF;
        4: -- Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
    IF State = 3 THEN
        FillTimer(IN := TRUE, PT := PT_REACT);
    ELSE
        FillTimer(IN := FALSE);
    END_IF;
END_IF;

IF FillValve AND DrainValve THEN
