CONSTANT PT_REACT : TIME := T#3s;

CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;
    1: // Fill
        IF NOT EStop AND Level < LVL_HIGH AND Level >= LIQ_MIN THEN
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        ELSIF Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            State := 2;
        END_IF;
    2: // Heat
        IF NOT EStop AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSIF Temp >= TEMP_SET OR Level < LIQ_MIN THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            State := 3;
