    3: // React
        IF NOT EStop AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSIF T#3s > PT_REACT OR Level < LIQ_MIN THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            State := 4;
        END_IF;
    4: // Drain
        IF NOT EStop AND Level > LVL_LOW AND Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        ELSIF Level <= LVL_LOW OR Level < LIQ_MIN THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
            State := 0;
        END_IF;
    ELSE
        State := 0;
END_CASE;

// Safety conditions
IF FillValve AND DrainValve OR NOT EStop OR Level < LIQ_MIN THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

