    State := 3;
ELSIF State = 3 AND TimePassed(PT_REACT) THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
ELSIF State = 1 OR State = 4 THEN
    FillValve := State = 1;
    Heater := FALSE;
    Agitator := FALSE;
