    Agitator := TRUE;
    DrainValve := FALSE;
END_IF;

IF State <> 1 AND State <> 4 THEN
    FillValve := FALSE;
END_IF;

IF State <> 2 THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

IF State = 4 AND Level > LVL_LOW THEN
    DrainValve := TRUE;
ELSE
