PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0: // Idle
            IF StartCycle AND Level < 90 THEN
                State := 1;
                Pump := TRUE;
                Valve := FALSE;
            ELSE
                Pump := FALSE;
                Valve := FALSE;
            END_IF;

        1: // Filling
            IF Level >= 90 THEN
                State := 2;
                Pump := FALSE;
                Valve := TRUE;
            END_IF;

        2: // Draining
            IF Level <= 10 THEN
                State := 0;
                Pump := FALSE;
                Valve := FALSE;
            END_IF;
    END_CASE;
ELSE
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

// Safety checks
ASSERT NOT(Pump AND Valve);
ASSERT NOT(Pump AND Level >= 90);
ASSERT NOT(Valve AND Level <= 10);

END_PROGRAM

