    Pump := FALSE;
    Valve := TRUE;
ELSIF State = 2 AND Level <= 10 THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0: -- Idle
            IF StartCycle AND Level < 90 THEN
                State := 1;
            END_IF;
        1: -- Filling
            IF Level >= 90 THEN
                State := 2;
            END_IF;
        2: -- Draining
            IF Level <= 10 THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    0: -- Idle
        Pump := FALSE;
        Valve := FALSE;
    1: -- Filling
        Pump := TRUE;
        Valve := FALSE;
    2: -- Draining
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

END_PROGRAM

