VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgnitionTimer : TON;
END_VAR

CASE State OF
    0: // Off
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := T#3s);
        END_IF;

    1: // Pre-purge
        IF PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE, PT := T#2s);
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2: // Ignition trial
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
END_CASE;

END_PROGRAM

