        IgnitionTimer(IN := TRUE, PT := T#2s);
        IF Flame AND IgnitionTimer.Q THEN
            State := 3;
        ELSIF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3: // Run
