    PT_IGN : TIME := T#2s;
END_VAR
VAR
    State : INT := 0;
END_VAR

CASE State OF
    0: -- Off
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1: -- Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF T#3s.Q THEN
            State := 2;
        END_IF;
    2: -- Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF NOT EStop OR StopPB OR Flame THEN
            State := 0;
        ELSIF T#2s.Q THEN
            State := 3;
        END_IF;
