PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF StartPB AND NOT StopPB AND NOT C3 THEN
                State := 2;
            END_IF;
        2:
            IF StartPB AND NOT StopPB AND C3 AND NOT C2 THEN
                State := 3;
            END_IF;
        3:
            IF NOT StartPB OR StopPB THEN
                State := 0;
            END_IF;
    END_CASE;

    CASE State OF
        0:
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        1:
            C1 := FALSE;
            C2 := FALSE;
            C3 := TRUE;
        2:
            C1 := FALSE;
            C2 := TRUE;
            C3 := TRUE;
        3:
            C1 := TRUE;
            C2 := TRUE;
            C3 := TRUE;
    END_CASE;
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    T1(IN := TRUE);
    T2(IN := TRUE);
ELSIF StartPB AND T1.Q AND T2.Q THEN
    CASE State OF
        0: 
            IF T2.Q THEN
                State := 1;
                T1(IN := TRUE);
            END_IF;
        1: 
            IF T1.Q THEN
                State := 2;
                T2(IN := TRUE);
            END_IF;
        2: 
            IF T1.Q AND T2.Q THEN
                State := 3;
            END_IF;
    END_CASE;
END_IF;

C1 := State >= 2;
C2 := State >= 3;
T1(PT := T#2s);
T2(PT := T#2s);

END_PROGRAM

