    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    SeqTimer1 : TON;
    SeqTimer2 : TON;
END_VAR

SeqTimer1(IN := NOT EStop AND NOT StopPB, PT := T#2s);
SeqTimer2(IN := NOT EStop AND NOT StopPB, PT := T#2s);

CASE State OF
    0:
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        C3 := TRUE;
        IF SeqTimer1.Q THEN
            State := 2;
        END_IF;
    2:
        C3 := TRUE;
        C2 := TRUE;
        IF SeqTimer2.Q THEN
            State := 3;
        END_IF;
    3:
        C3 := TRUE;
        C2 := TRUE;
        C1 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
    SeqTimer1(IN := FALSE);
    SeqTimer2(IN := FALSE);
END_IF;

