PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF StartPB AND State = 1 AND TON_C3_2.Q THEN
    State := 2;
ELSIF StartPB AND State = 2 AND TON_C2_2.Q THEN
    State := 3;
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        TON_C3_2(IN := TRUE, PT := T#2s);
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        TON_C3_2(IN := TRUE, PT := T#2s);
        TON_C2_2(IN := TRUE, PT := T#2s);
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        TON_C3_2(IN := TRUE, PT := T#2s);
        TON_C2_2(IN := TRUE, PT := T#2s);
END_CASE;

IF State >= 2 THEN
